#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber ---
patchFile('siman_010/mechaber/part-001.txt', 'mechaber', {
  '1#main': `Additional knife laws. In it are 3 seifim. A knife of attendants of avodah zarah—whether new or old in which there is no concern of defilement from avodah zarah—is permitted to slaughter with it a healthy animal, because it spoils (the animal) and does not provide benefit. But it is forbidden to slaughter with it a dangerously ill animal, because it repairs (heals). A knife of a gentile that was sharpened on his sharpening wheel (see above siman 121)—or if it was fine so that it had no nicks and he stuck it in hard ground ten times and afterward slaughtered with it—it is permitted. And if he slaughtered with it without any kashering, he rinses the slaughterhouse; and if he peeled (the meat), this is preferable (most poskim). {Rama: And in a situation of pressure where he has no other knife, it is permitted to slaughter with it in such a manner l'chatchila; but he should not slaughter intending to peel afterward (Tur in the name of the Rosh and R' Yerucham).}`,
  '2#main': `A knife with which one slaughtered kosher—even though it is soiled with blood—is permitted to slaughter with it another time; but it is forbidden to cut with it boiling (hot) meat; and it is permitted to cut with it cold (meat) by rinsing, that one rinse it first. {Rama: And if one wants to kosher it (hag'alah) to eat boiling with it, pouring suffices for hag'alah even though it is not kli rishon (Orach Chaim general rule 58 in the name of Maharam).}`,
  '3#main': `A knife with which one slaughtered a treifah—it is forbidden to slaughter with it until one rinses it when cold or wipes it with something hard. And they are accustomed now to wipe it well with animal hair between each slaughter and slaughter, and this is fine; and if he slaughtered with it without rinsing, he rinses the slaughterhouse. And if he is accustomed to slaughter treifot with it frequently, he needs sticking (the knife) ten times in hard ground.`,
});

// --- siftei-kohen ---
patchFile('siman_010/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `<b>New.</b> Rather, he cut with it a section of wood for avodah zarah—Gemara: because attendants of avodah zarah are not forbidden until they use them, as below siman 139.`,
  '1#ב': `<b>Or old in which there is no concern of defilement from avodah zarah.</b> That is to say, that they kashered it in a manner in which there is no concern of defilement from avodah zarah, as below siman 121.`,
  '1#ג': `Permitted to slaughter with it a healthy animal. It implies even l'chatchila; and below siman 142 seif 2 he wrote: a knife of avodah zarah with which he slaughtered—is permitted, etc.—which implies it is forbidden l'chatchila when it speaks of one not kashered from defilement of avodah zarah; and so is explained from Hagahot HaRav there. And if a gentile's knife needs immersion before slaughter—see above siman 120 seif 5.`,
  '1#ד': `<b>Because it spoils.</b> And this is not the benefit of keeping it alive—for its monetary value would have been greater after slaughter, when it stood for three things: to grow, to bear young, and for plowing, and for eating (Rashi); and see above siman 142.`,
  '1#ה': `<b>And it is forbidden to slaughter with it a dangerously ill animal.</b> Thus wrote the Tur; and if he slaughtered with it, the Rashba wrote: he should take the benefit to the Dead Sea and it is permitted—and how much is that? Enough for the wage of a knife to slaughter with it. And I cannot (agree)—the Rosh wrote: one need not, for with such slight benefit it is permitted b'dieved, end of his words. The Mechaber speaks here only regarding the prohibition of warning not to slaughter with it l'chatchila; but regarding the prohibition of the animal itself he relies on what he wrote in siman 142, where these laws are primary—and thus: a knife of avodah zarah with which he slaughtered, etc., a dangerously ill animal is forbidden, therefore; and this is the language of the Rambam, meaning that the entire animal is forbidden, as he wrote there in s.k. 6. And it is astonishing on the Bach, who wrote: it appears from what the Shulchan Aruch wrote in general, and he did not write that one should take the benefit to the Dead Sea—that he ruled like the Rosh, etc. And also on the Taz it is difficult, for here he wrote: and this is specifically l'chatchila, but if he slaughtered with it one does not forbid it because of such slight benefit, therefore; and in siman 142 he wrote: and if he slaughtered with it, he takes the benefit to the Dead Sea. And it is possible that here he means not to forbid the entire animal—and this is strained; but it appears to me that all the Rosh's analysis and proofs are only to forbid the entire animal, similar to one who baked bread in an oven—for all the bread is forbidden in his view where it was not mixed, and taking benefit to the Dead Sea does not help, as below siman 142; but the Rosh concedes to the Rashba that here one takes the benefit of the knife-wage to slaughter with it to the Dead Sea, and so is proved explicitly in R' Yerucham there. But the Tur, Beit Yosef, Maharshal there siman 13, and other acharonim understood that the Rosh does not require even taking benefit to the Dead Sea—and this requires study. Nevertheless the Ran, Maharshal, and Bach ruled like the Rashba—and this is not like the Mechaber below siman 142; see there.`,
  '1#ו': `<b>A knife of a gentile, etc.</b> From the Mechaber's general wording it appears he speaks of a plain knife; and he holds like the Rashba that although we hold below siman 122 that a plain vessel of a gentile is not ben yomo, a knife is different—because since its use is frequent, presumably its grease is smeared on its surface and forbids even if it is not ben yomo; and so too in siman 94 s.k. 28, that this is the Mechaber's and HaRav's view there, and so is the consensus of the poskim; and so appears explicitly from Rashi in the first chapter of Chullin daf 8b, s.v. tzonen, and from the words of all the poskim there regarding radish cut with a meat knife; and Maharshal there siman 12 inclines to the Rosh and his colleagues. However, if the knife is ben yomo—even if it appears to the eye that it is clean of all fat and he slaughtered with it—peeling is required, as appears from Tosafot, the Rosh, Semag end of negative commandment 137, Semak, Hagahot Maimoniyot chapter 17 from Hilchos Ma'achalot Assurot; and it is possible that the Rashba also concedes to this, and the reason is: since it is ben yomo it absorbs in beit hashchitah what is in the knife's peel; and although there is no power in the heat of beit hashchitah to expel the knife's absorption, as the Rashba wrote (and the Tur cites it)—and his support that therefore sticking ten times in hard ground helps even if it is ben yomo, as explained in Tur Orach Chaim daf 15, 16—nevertheless, if he did not stick it, there is power in the heat of beit hashchitah to expel what is in the knife's peel; but if he stuck it and that thin peel went away, there is no power in the heat of beit hashchitah to expel the absorption inside that peel—and so he proved in Perishah 66; see there. And the Bach in his last pamphlet challenged him and ruled that for the Rashba, if it is clean—even if ben yomo—it is permitted; and I did not stand on the end of his view—and think.`,
  '1#ז': `<b>That it has no nicks.</b> Meaning notches—for if it has notches, sticking does not help, as below siman 121; and so the Rambam there calls notches pegimot, and the Beit Yosef cites it there; and see there the laws of sharpening and sticking.`,
  '1#ח': `<b>And afterward slaughtered with it—it is permitted.</b> It implies specifically b'dieved, but l'chatchila he should not slaughter; and this is specifically with sticking, as appears explicitly from the Rambam's words there; but sharpening appears from his words there that it helps even l'chatchila, and so the Mechaber in siman 121; and it is possible that even according to the Rav there that sharpening does not help for hot l'chatchila, nevertheless here for shechitah one may be lenient, since in any case there are poskim who permit even with sticking l'chatchila, and there are poskim who hold beit hashchitah is cold.`,
  '1#ט': `<b>And therefore one should peel it.</b> Meaning by law; and so wrote in Darkei Moshe, and so Maharshal there and the Bach; and they seized on the Mechaber that he ruled like the Rambam where most poskim and nearly all agreed that peeling is required—for correct reasons. However, what the Bach wrote—that even b'dieved the dish is forbidden, like any thing cooked without peeling—see there siman 69 s.k. 64 [should be 60] and siman 91 s.k. 7 [should be 8].`,
  '1#י': `<b>Permitted to slaughter with it in such a manner, etc.</b> Meaning by sticking; and so is explained in Darkei Moshe and the Bach and Taz; and in Sefer Lechem at the end of daf 136 he wrote that this gloss must be deleted—see there; and I did not reach the end of his view (and he thought it means it should be turned over in the conclusion—but he should not slaughter, etc.—must be before the opening, and in a place of pressure, etc., end of his words).`,
  '1#כ': `<b>But he should not slaughter intending, etc.</b> The Bach ruled from the poskim's implication that even with a knife that is not ben yomo and is clean, it is certainly forbidden l'chatchila; and Maharshal there permitted a plain knife to slaughter l'chatchila intending to peel—for even if he does not peel afterward there is no prohibition, and it is like what we hold in siman 1: permitted to give him l'chatchila to slaughter on condition that he inspect afterward if he is expert—because even if he does not inspect, it is permitted b'dieved, therefore; and this is according to his view that he holds a plain knife is clean. And even according to his view one can say: it is not comparable to siman 1, for here since it is not ben yomo it is forbidden rabbinically because of a decree lest ben yomo—as below siman 122—if so, in every case it is forbidden l'chatchila so that one not come to permit ben yomo.`,
  '2#א': `<b>Even though it is soiled with blood—it is permitted, etc.</b> It implies explicitly that it is permitted to slaughter with it when soiled even without any rinsing at all; and furthermore, regarding a knife with which one slaughtered treifah, the Taz wrote in s.k. 3 specifically that rinsing is required—and the poskim wrote the reason: because in any case there is much blood in beit hashchitah and it does not absorb, because the simanim are busy expelling blood; and see above s.k. 18.`,
  '2#ב': `<b>But forbidden, etc.</b> It implies that even if he slaughtered only once, it is forbidden afterward to cut boiling with it by rinsing; and so is the view of the poskim; and so ruled Darkei Moshe and Maharshal there.`,
  '2#ג': `<b>Forbidden to cut with it boiling.</b> And b'dieved, if he cut boiling without hag'alah—the Taz did not explain its law; and it appears that although he holds—and so Semag, R' Yerucham, and other poskim—that hag'alah is required, that is l'chatchila; but if he cut boiling b'dieved after rinsing well, it is permitted—for he brought Rashi's wording in general regarding cold beit hashchitah, and the knife does not absorb because it is hard to absorb; and so it appears to me to resolve the Tur's view and Rabeinu Yerucham with what the Rosh wrote in the first chapter of Chullin and chapter 25—see there—that he wrote: according to the one who says beit hashchitah is cold, rinsing suffices (and even though regarding slaughtering treifah rinsing suffices, this is like b'dieved to kosher the knife between each treifah animal). And so the Rambam chapter 6: forbidden to eat boiling except with hag'alah, and if he cut boiling it is permitted, end of his words; and the Rav HaMagid wrote that he holds beit hashchitah is cold—see there. And even for the Rashba, who wrote that it is forbidden to cut boiling because it absorbs and returns and expels—nevertheless it appears that peeling suffices, for although it absorbed, it did not absorb more than a peel's worth—for even with a gentile's knife whose grease is smeared on its face and he slaughtered with it, peeling suffices even for the Rashba; therefore heat in beit hashchitah does not absorb more than a peel's worth; if so, the knife also absorbed a slight thing from beit hashchitah and does not forbid more than a peel's worth; and so Maharshal divides explicitly in chapter 25 siman 59 and rules thus; and so is explained in Orach Chaim general rule 58 law 14, who wrote: a knife with which he slaughtered and wants to cut something else hot needs hag'alah l'chatchila, for in beit hashchitah it boils, etc.; however if he cut b'dieved it is permitted with peeling even if hot, end of his words; and it appears that for this reason Orach Chaim and the Rav HaMagid permit hag'alah by pouring even though we hold below simanim 68 and 105 that pouring only expels a peel's worth—rather as explained: the knife did not absorb except a slight thing; and so Maharil in blood laws: peeling suffices if he cut boiling or something sharp.`,
  '2#ד': `<b>And permitted to cut, etc.</b> It implies that even if he slaughtered with it many times, it is permitted to cut cold by rinsing; and so the Taz; and so appears from the poskim; and so in Hagahot Maimoniyot chapter 6 in the name of Rabeinu Yehudah explicitly; and so appears in Darkei Moshe; and it is not comparable to one accustomed to slaughter treifot with it—for in seif 3 here it is different, because its prohibition is from blood, and blood slides and is not absorbed so much in the knife, as the poskim wrote.`,
  '2#ה': `<b>By rinsing.</b> It appears from the Taz not writing here too "or wipe with something hard" as adjacent in seif 3—therefore he holds that specifically there wiping helps because there is also the reason that the simanim are busy expelling blood, which is not so here; and so is proved explicitly in the Rosh in the first chapter of Chullin, who wrote: and even to cut cold with it we say in chapter 25: some say rinsing is required and some say rinsing is not required except for a thick slice; and the knife is the subject, end of his words—therefore according to what we hold, as those who say rinsing is required, wiping a thick slice does not help. And Maharshal in chapter 25 siman 59 wrote that it is a printing error in Ashrei and in the place it should say "and not in the Gemara," for the Gemara implies explicitly that for a thick slice its law is like rinsing, end of his words. And it is hard to corrupt all the books; and one can ask: if so, why did the Rosh need to say that a thick slice does not require it? And furthermore, we hold like the one who says rinsing is required—why did the Rosh need to explain the words of the one who says rinsing is not required? And furthermore, what relevance is this matter here? He should have written it below in chapter 25, where this matter's primary place is. Rather, certainly because the Rosh says here that the knife is the subject—not as Rashi explained, that it refers to cold meat cut with it—the Rosh comes to say: how is it possible that the knife is the subject? If so, why does the one who says rinsing is not required not require rinsing, when slaughter-blood is visible on its face? Therefore he says: rinsing is not required except for a thick slice. And that he did not state in general that rinsing is not required but only wiping—is because he holds that any wiping that is not like a thick slice is not wiping at all; and so the Rashba in Ma'adanei Yom Tov daf 73b on the words of the Ra'ah in Beit HaBechirah, who wrote: where did he find this simple comparison that they made good wiping like rinsing? And if because we say regarding a knife with which one slaughtered treifah: rinse it when cold—and if there is a thick slice, more is not needed—on the contrary, infer the opposite: if wiping and rinsing are equal, why say thus? It is obvious—and what does it teach? Rather, to say rinsing is not required; even wiping suffices. And how did he not pay attention to what they said: regarding a knife with which one slaughtered and wants to eat cold with it—rinsing is required, and they did not say wiping is required? We learn that rinsing is required and wiping does not suffice. And the one who says rinsing is not required—not to say that nothing is required to kasher it without anything, for slaughter-blood is on it, end of his words; and so it appears to my humble view from what we say regarding slaughter—and if there is a thick slice, more is not needed—and this was not omitted throughout the entire Gemara to say so in another place where rinsing is mentioned; therefore we say specifically regarding slaughter that wiping suffices here for the reason I explained; but not in general—and this is also the Rosh's view.`,
  '3#א': `<b>Until one rinses it when cold.</b> The reason: treifah grease adheres to the knife's sides and is absorbed in beit hashchitah; for although the simanim are busy expelling blood, nevertheless it absorbs grease—so write the poskim; and we divide below siman 70; and specifically here rinsing suffices and not above regarding the knife mentioned—for there the knife is already forbidden and the meat is soft to absorb; but here the knife is hard to absorb except by boiling, and not by heat in beit hashchitah; and here there is only grease on the knife, therefore rinsing suffices—Rashi and poskim. And for the Rashba, who holds the knife absorbs somewhat by heat in beit hashchitah and through the knife's pressure he holds that nevertheless it is not expelled by heat in beit hashchitah and the knife's pressure except in actual boiling, as he wrote in his novellae and in Tur Orach Chaim.`,
  '3#ב': `<b>Between each slaughter and slaughter.</b> Because we are concerned lest he find a treifah; and the Bach wrote: specifically for an animal; but for birds, where treifot are not common, the custom is not to wipe; however, because of the prohibition of eiver min hachai one should warn slaughterers to wipe even for birds; and wiping with birds' feathers does not help—rather something hard is needed, such as a piece of wet cloth, or rinsing when cold between each slaughter and slaughter, end of his words; and he brought proof from what the Gemara asks for the one who permits in hot: treifah also absorbs forbidden matter, etc. And one can reject his proof; and so Hagahot Ashrei from Mahariach and Maharshal first chapter of Chullin siman 12: rinsing is not required at all even for cold with a knife with which he slaughtered kosher; and so the Razah and Rashba in his novellae daf 10, 13, and Tur Orach Chaim, and the Mordechai, and the Agudah; and so appears explicitly in Ashrei and R' Yerucham; and so is the Taz's view, as he wrote in s.k. 12; and so Semag end of negative commandment 137, Hagahot Maimoniyot chapter 6 from Hilchos Ma'achalot Assurot, and Orach Chaim general rule 58 law 15.`,
  '3#ג': `<b>And if he slaughtered with it without rinsing, etc.</b> So too the Tur; and they seized on him—Maharshal there and the Bach—that although l'chatchila rinsing suffices for the knife because it is hard to absorb except by boiling or because it does not expel—nevertheless where he did not rinse, it absorbed in beit hashchitah from grease that is on it visibly and peeling is required, for it is no worse than the knife mentioned—and as appears from Rashi; and so is explained in Sefer HaTerumah siman 70; and so the Rashba; and so Ra'avan siman 211; and so appears explicitly in the Ran in chapter 25: slaughtered treifah with it is like the knife mentioned in this regard.`,
  '3#ד': `<b>He rinses beit hashchitah.</b> One should not ask: in any case rinsing is needed before salting because of blood, as below beginning of siman 69; and even for roasting we hold rinsing is required, as the Rav wrote siman 77—the Rashba and Ran in the first chapter of Chullin in the name of Rabeinu Yona already answered: if because of blood, ordinary rubbing suffices until the water runs without appearance of blood; but now because of forbidden grease we require great rubbing with the hands well, in order to remove the knife's fat that adhered by estimation, end of his words (so too there for the one who says in the Gemara regarding the knife mentioned: rinse—but we hold peel). And so all of them (and with this one can answer what the Taz wrote: forbidden to slaughter with it until one rinses it when cold—and we should not say he may slaughter without rinsing and rinse afterward; presumably since his way is rinsing, as below siman 139, it must be—rather certainly here we require rinsing well, for ordinary rinsing does not suffice; and so one can say below siman 64 seif 7, where there too the Rashba and Rav HaMagid wrote that great rubbing with the hands well is required, etc., see there). And the Derishah strained himself here in vain, and these poskim's words escaped him.`,
  '3#ה': `<b>And if he is accustomed to slaughter.</b> Rashi explained: such as he slaughtered many animals and found several animals among them treifot on inspection—he should no longer slaughter except stick, etc.; and the Bach wrote: the kosher animals found among them were kashered by the wiping he did in the interim—and see there.`,
  '3#ו': `<b>He needs sticking, etc.</b> Meaning: and afterward slaughter l'chatchila; and so Darkei Moshe and Derishah; and even though with the knife mentioned above sticking does not help l'chatchila—this is because it absorbed much through actual boiling, which is not so here; and this distinction appears in Rashi and is mentioned in Tosafot and other poskim.`,
});

// --- turei-zahav ---
patchFile('siman_010/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#א': `<b>New.</b> Meaning: they did not use it with hot food; but nevertheless they already used it for any matter of avodah zarah, and there is no prohibition from what it absorbed—only from attendants of avodah zarah.`,
  '1#ב': `<b>Because it spoils, etc.</b> In its lifetime it stands to grow, bear young, and for plowing; and what is difficult about this from the Shabbat prohibition I wrote in siman 121 seif 12; and see there what I wrote—that one should wonder at the Rama's ruling there.`,
  '1#ג': `<b>And forbidden to slaughter with it a dangerously ill animal.</b> And if he did so b'dieved, the Tur wrote in the name of the Rashba that he should take the benefit to the Dead Sea—and this is enough for the knife-wage to slaughter with it; and the Rosh permits b'dieved, since the animal already grew and lacks only being fit to eat through shechitah—even though he enjoyed much through shechitah, the Sages did not forbid its enjoyment b'dieved through prohibitions of benefit; and Rabbenu Yerucham wrote that one should rule like the Rashba.`,
  '1#ד': `<b>In hard ground.</b> Thus wrote Tur Orach Chaim the long one: even if it is ben yomo, this suffices—for there is no heat in beit hashchitah to expel the knife's absorption, end of his words; see what I will write shortly on this. But in the Mordechai it is explained that sticking in the ground does not help except when it is not ben yomo; and one should be stringent like his words if it is known to be ben yomo, for hag'alah is required.`,
  '1#ה': `<b>He rinses beit hashchitah.</b> It is difficult—for in any case all meat needs rinsing before salting. The Ran answered: here it speaks even for roasting; he also answered in the name of Rabeinu Yona: for blood, rubbing in water suffices; but here because of forbidden grease, great rubbing with the hands well is required.`,
  '1#ו': `<b>And therefore one should peel it.</b> Explanation: it is a full obligation—not as the Shulchan Aruch implies, that it is only hiddur mitzvah; and so Rabbenu Yerucham: one should be stringent by Torah law. The rishonim asked: why is this different from a knife of Kutim, for we hold a plain vessel of Kutim is not ben yomo—and why different from a radish of chiltit in the chapter "One may not stand," and sharp things in siman 96 forbidden with a Kutim knife because its sharpness spoils it and makes it praiseworthy—implying that without its sharpness it would be permitted? The Rosh and Tosafot answered: here it speaks where the knife is known to be ben yomo; and the Rashba wrote in the name of Rabeinu Yona: here it is forbidden because of smeared prohibition visible on the knife, and whatever is visible is not spoiled even in many days; but with a radish of chiltit there is no concern of visible prohibition, for there it speaks of buying from a shopkeeper, and a plain shopkeeper has clean vessels, and there is only concern of absorbed prohibition—and in this, if it is not ben yomo, it helps. And in Perishah he challenged the Rosh, who is lenient here regarding fat on the knife, from siman 96 regarding radish cut with a knife, etc.; and he answered: here it speaks of a plain vessel of Kutim—as we say regarding it, the plain is not ben yomo, so too we say its plain is well wiped; but there it speaks of an Israelite vessel—as we say its plain was ben yomo, so too its plain is not wiped. And he was not precise—for in siman 122 seif 4 he ruled explicitly that even with an Israelite vessel we say their plain is not ben yomo. And one must explain in the Tur, which brought the dispute of the Rosh and Rashba, in what they argue and why the Rosh was not also concerned for visible prohibition on the knife and why he relied on leniency in a Torah doubt—and he said: he holds that even with visible prohibition there is reason for spoilage, in which all agree, as proved in many places—why different from a piece of prohibition? And I found in Mishmeret HaBayit, who wrote: this answer—that the reason is grease visible on the knife—I hesitate about somewhat; for a recognizable thing, smeared slight grease on the knife's sides, is spoiled somewhat even temporarily, and all the more when it is not ben yomo; and they do not bring proof from a piece of meat and abundant fat standing alone for smearing only; and furthermore through iron it receives taste and is spoiled, and experience testifies to this, end of his words; and it appears Tosafot and the Rosh also hold thus here, therefore they needed another answer. And one must understand the Rashba's and Rosh's views here: the Rashba holds beit hashchitah is called boiling on one side—that the knife can receive from beit hashchitah grease, blood, and anything, but it is not fully boiling regarding expelling the knife's absorption into beit hashchitah; receiving into the knife is easier than expelling from it; therefore if he slaughtered with a Kutim knife there is no concern it will expel into the simanim what the knife absorbed—for beit hashchitah has no power to boil so much; rather concern is from what is visible on the knife from prohibition already cut; in this, sticking in the ground helps; therefore the Rashba called this "somewhat boiling." And in Derishah and Perishah he understood from "somewhat boiling" that therefore the knife absorbs in beit hashchitah somewhat—and from this entered pilpul; and he did not have Tur Orach Chaim before him, who wrote explicitly as I mentioned that it does not absorb at all from knife to simanim; and what the Tur wrote in siman 105—that for the Rashba heat in beit hashchitah expels—means one side we mentioned, from prohibition to knife, but not from knife to simanim; and in Perishah he did not notice this distinction. And it appears clear that also the Rosh, who argues with the Rashba and establishes it in ben yomo, also holds beit hashchitah does not absorb from the knife's absorption, but absorbs from what is visible on the knife—all the more when ben yomo, as he wrote; therefore sharpening and sticking help the knife, as in the primary source Tosafot brought in the first chapter of Chullin (daf 8): you might say: if it absorbs the absorption, what does sticking help for what is absorbed? Rather, as I explained, both hold the primary concern is from what is visible on the knife; but for the Rosh, even in this it must be ben yomo, and for the Rashba ben yomo is not required in this—as explained clearly after investigation; and with this what they ask is resolved: why did the Tur bring the Rashba's plain view that sharpening and sticking help, since for the Rosh they do not help—and according to what I wrote, it is fine.`,
  '1#ז': `<b>Permitted to slaughter with it in such a manner, etc.</b> Explanation: if he sharpened on a whetstone or stuck in hard ground; and it appears the Rama does not speak here except of a plain knife; but where it is known to be ben yomo he should not do so l'chatchila—rather as written shortly in the name of the Mordechai; and so concludes Orach Chaim.`,
  '1#ח': `<b>Intending to peel.</b> See what I wrote on this in siman 91 seif 4.`,
  '2#א': `<b>Soiled with blood.</b> He explained in Tur Orach Chaim that beit hashchitah is like boiling for this—that it absorbs through the knife's pressure even if not soiled with blood—and not like Rashi; and his proof from that a knife with which he slaughtered is forbidden to cut boiling—and the reason is nevertheless beit hashchitah boils somewhat and absorbs blood in the knife; nevertheless permitted to slaughter with it because the simanim are busy expelling blood and do not absorb, as in the Gemara.`,
  '2#ב': `<b>Permitted to slaughter with it another time.</b> It implies without any rinsing or wiping; and so Maharshal concludes; and it is wondrous from what is in Chullin (daf 8): there is an opinion regarding a treifah knife that hag'alah in hot water is required, and it asks on it: why is treifah different, that it absorbs prohibition—for when he slaughtered kosher it also absorbed eiver min hachai, and the knife should require hag'alah even when slaughtering kosher? And it answers: when does the knife absorb? While the animal lives; and when does it live? At the completion of shechitah—at that moment there is no eiver min hachai—learn that the heter is only because the absorption is only at the end; but if the prohibition is not from absorption but only from what is visible on the knife, it certainly forbids even before completion of shechitah—for this does not need heating; and according to the one who says beit hashchitah is cold, there is prohibition from what is visible on the knife; if so, when slaughtering kosher it should be forbidden to slaughter afterward, since visible prohibition of eiver min hachai is on the knife. And it appears we only ask if the concern is taste absorbed in the knife that will return and absorb in the simanim—we also find in kosher absorption of forbidden absorbed matter from eiver min hachai; but if the concern is only what remains visible, this does not apply to eiver min hachai—for there is no substance of eiver min hachai, only mixed in blood; and since blood does not absorb because simanim are busy expelling their blood, therefore no prohibition even from eiver min hachai; rather they were concerned about treifah animal grease that adheres (in the matter) to the knife, which is something that adheres and joins even at completion of shechitah—in this they were certainly concerned and required kashering the knife, as above. And I saw in Hagahah in the Agudah first chapter of Chullin: also when slaughtering kosher, wiping the knife is required because of eiver min hachai; and therefore it does not ask for the one who says regarding a treifah knife in cold: there is eiver min hachai prohibition, as it asks for the one who says in hot—therefore, end of his words; and Orach Chaim brought and strengthened his words to say: even according to the conclusion that it absorbs only at completion of shechitah—meaning it does not absorb so much that hag'alah is required; but in cold nevertheless it absorbs somewhat before completion of shechitah; and therefore he ruled: even when slaughtering a bird, wiping with something hard is required. And to me it appears as I wrote: otherwise sticking in the ground would be required, like one who absorbs treifot frequently—and we do not find sticking except for a knife that frequently has treifah; and furthermore, how did the Torah command any shechitah—shall we say that at the beginning of shechitah it absorbs somewhat from eiver min hachai prohibition and forbids at completion? Rather it is clear this has no basis and no one is concerned for it at all.`,
  '2#ג': `<b>To cut cold with it.</b> He did not need to write this law—for even for treifah slaughter, rinsing helps even to slaughter with it again, as seif 3 says; rather he mentioned cold law here since he mentioned boiling law; and it is simple that if he cut cold without rinsing the knife first, he rinses that cold afterward.`,
  '2#ד': `<b>Pouring suffices for him.</b> Because beit hashchitah is not fully boiling, as the Tur wrote in the name of the Rashba.`,
  '2#ה': `<b>Even though it is not kli rishon.</b> With kaf, not bet—meaning kli sheni.`,
  '3#א': `<b>With which he slaughtered treifah.</b> Here it is not relevant to say: since the simanim are busy expelling blood they do not absorb, as in seif 2—for here it absorbed grease and the busyness of expelling blood does not nullify it; and that rinsing the knife helps is because beit hashchitah is not so boiling regarding expelling what the knife absorbed; rather the primary prohibition is from forbidden grease adhering on the knife's face, and it is absorbed in the simanim; therefore rinsing what is on the knife's face helps—so is the Rashba's view in Tur Orach Chaim: heat in beit hashchitah helps that the knife absorbs, but regarding expelling the absorption into the meat it does not help; therefore the Rashba called this "somewhat boiling," not fully boiling.`,
  '3#ב': `<b>Until one rinses it when cold.</b> Learn for a Kutim knife in seif 1: cold rinsing of the knife does not suffice—for a knife mentioned is different, since he used it frequently and much adhered to it; therefore it will not be removed by ordinary rinsing.`,
  '3#ג': `<b>He rinses beit hashchitah.</b> The Beit Yosef wrote on this: it is simple that just as rinsing helps for the knife itself, so too rinsing beit hashchitah suffices, end of his words; and Rabbenu Yerucham wrote on the Tur's words here: I wonder where he got this; and it appears by reasoning that peeling is required; and so in Sefer HaTerumah; and all the more—for even a knife mentioned that is well wiped, only absorbed prohibition in it, we say it absorbed through shechitah; all the more grease that adhered and is not wiped requires peeling, end of his words; and his reasoning appears good: it is simple that rinsing does not help for what was absorbed, only for what is on its face; and since with the knife mentioned beit hashchitah needs peeling, apparently heat in beit hashchitah causes the knife to absorb—so too it absorbs in it; and what does rinsing the meat help, since there is visible prohibition on the knife from treifah grease—otherwise the knife would not need rinsing; rather certainly it absorbed and re-absorbs afterward through heat in beit hashchitah; and so explicitly in Tur Orach Chaim, who wrote: and since so, even though we hold regarding a treifah knife like the one who says cold, we hold like Rav with a knife mentioned—that one peels, because prohibition adhered visibly on the knife's face and was absorbed in the meat with heat in beit hashchitah; and the same for a knife with which he slaughtered treifah: if he slaughtered before rinsing, he peels like Rav, etc. And it appears to resolve the Tur's view: since there is already dispute regarding a Kutim knife whether the meat needs peeling or rinsing—and although one should rule stringently there to peel—nevertheless here the prohibition is lighter than a knife mentioned; one may rely on the view that rinsing suffices even for a knife mentioned; and nevertheless for practical law one should rule stringently that here too peeling is required, as Rabbenu Yerucham wrote and as Orach Chaim concludes; and there is great wonder on the Beit Yosef, who wrote it is simple like the Tur's view, when there is a great and mighty dispute against him.`,
  '3#ד': `<b>Accustomed to slaughter treifot with it, etc.</b> For this is like a knife mentioned; if so, if he transgressed and slaughtered without sticking, it is obvious that here he must peel beit hashchitah—even according to the Tur I mentioned before; and Rabbenu Yerucham wrote: I cannot understand his view—who is accustomed to slaughter treifot with a knife? How would he know beforehand it would become treifah? And it is not found that a person designates a knife for treifah slaughter; rather it speaks that he slaughtered many animals and found several among them treifah on inspection—he should no longer slaughter with it except stick ten times in hard ground. And even if you say the Tur did not intend this, nevertheless one should instruct thus; and so one should do each time at harvest season from house to house, end of his words. And it appears to my humble view: certainly l'chatchila one need not be concerned when slaughtering many animals that many will be treifot one after another without interruption of kosher slaughter in the interim—and whenever there is kosher slaughter in the interim, it is not called "accustomed" to prohibition, and it is not like a knife mentioned; rather if it is clear he slaughtered animals one after another and they became treifah from what he slaughtered afterward without sticking in hard ground, he must peel that animal's beit hashchitah. And it appears that with three treifah slaughterings combined he is called accustomed to slaughter treifot with it—for with three times there is a chazakah, as I brought below siman 100 seif 4 regarding three worms; but l'chatchila wiping well with hair as written here suffices—except that Maharshal wrote that now they do not wipe well as appropriate, only casually, and the teacher must warn them about this.`,
});

// --- baer-heitev ---
patchFile('siman_010/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `<b>New.</b> Meaning: they did not use it with hot food; but nevertheless they already used it for any matter of avodah zarah—such as he cut with it a section of wood; for attendants of avodah zarah are not forbidden until they use them, as below beginning of siman 139.`,
  '1#ב': `<b>Avodah zarah.</b> Meaning: that they kashered it, as below siman 121.`,
  '1#ג': `<b>Spoils.</b> And the reason: because in its lifetime it stands for three things—to grow, bear young, and for plowing, and for eating; however one who slaughters on Shabbat and Yom Tov we do not say he spoils; only regarding avodah zarah we say thus; and the Taz wrote in siman 121 seif 12: the same applies to one under a vow of benefit from his fellow—that it is forbidden to slaughter an animal for him, for it is a daily occurrence that we hire a slaughterer, and we do not say he spoils.`,
  '1#ד': `<b>Repairs.</b> And he wrote in the Shach: and if he transgressed and slaughtered with it—see below siman 142, where it implies the entire animal is forbidden; but Maharshal and all the acharonim disagreed with the Mechaber and ruled that taking benefit to the Dead Sea suffices—meaning enough for knife-wage to slaughter with it; and the Rosh permits b'dieved, for with such slight benefit it is permitted b'dieved; and Rabbenu Yerucham wrote that one should rule like the Rashba.`,
  '1#ה': `<b>His (wheel).</b> And he wrote in the Shach: from his writing in general it implies even with a plain knife that is not ben yomo he forbids, because its use is frequent—therefore he forbids if he did not sharpen on a wheel, for presumably grease is smeared on its face; however if the knife is ben yomo, even if it appears clean and he slaughtered with it—if he did not sharpen on a wheel and did not stick it, peeling is required, because as long as it was not stuck in hard ground, heat in beit hashchitah has power to expel what is in the knife's peel.`,
  '1#ו': `<b>Times.</b> And he wrote in the Shach: it implies from here that even if ben yomo, sticking helps; and he explained: specifically ten times in hard ground—not as people are accustomed to stick and leave it in the ground; rather the essence is to stick and withdraw and stick until ten times one after another in one day. However from the Mordechai's words it appears sticking does not help with a ben yomo knife, and one should be stringent with ben yomo that peeling is required; and from the Rambam's words it appears even for not ben yomo sticking does not help; and so if it has pegimot—meaning notches—sticking also does not help, as below siman 121.`,
  '1#ז': `<b>Permitted.</b> And so in the Shach: it implies specifically b'dieved it is permitted, and specifically with sticking; but sharpening is permitted l'chatchila, as below siman 121; and even according to the Rama who forbids there using it hot—nevertheless for beit hashchitah he concedes it helps.`,
  '1#ח': `<b>To peel it.</b> So in the Shach—and this is by law; however what the Bach wrote—that even b'dieved the dish is forbidden, like anything cooked without peeling—see siman 91; and according to the Beit Yosef's view that rinsing suffices, great rubbing with the hands well is required.`,
  '1#ט': `<b>L'chatchila.</b> The Taz explained: if he sharpened on a whetstone or stuck in the ground—and all this with a knife that is not ben yomo; but with ben yomo he should not do so l'chatchila.`,
  '1#י': `<b>Afterward.</b> And so in the Shach in the name of the Bach: even with a knife that is not ben yomo and is clean, it is forbidden l'chatchila—and not like Maharshal.`,
  '2#א': `<b>Another time.</b> And the Shach wrote: permitted to slaughter with it when soiled even without rinsing, because the simanim are busy expelling blood and do not absorb.`,
  '2#ב': `<b>Boiling.</b> And he wrote in the Shach: even if he slaughtered only once, it is forbidden afterward to cut boiling l'chatchila if not with hag'alah; and pouring suffices for hag'alah; and b'dieved if he cut something boiling without hag'alah—only after rinsing or something sharp, peeling suffices; the reason: the knife absorbed a slight thing from beit hashchitah; therefore pouring suffices for hag'alah even l'chatchila, and b'dieved by peeling.`,
  '2#ג': `<b>First.</b> And he wrote in the Shach: even if he slaughtered with it many times, permitted to cut cold by rinsing—and specifically by rinsing, but wiping does not help, as he wrote afterward in seif 3, because in seif 3 it speaks of beit hashchitah and there is another reason that simanim are busy expelling blood, which is not so here, end of his words. And if he cut cold without rinsing, he rinses that cold afterward.`,
  '3#א': `<b>This is fine.</b> And the reason is in the Shach: because treifah grease adheres to the knife's sides and is absorbed in beit hashchitah; for although they are busy expelling blood, nevertheless it absorbs grease; and that rinsing suffices here and not above with a gentile's knife is because there the knife is already forbidden and the meat is soft to absorb; but here the knife is hard to absorb—it absorbs only through actual boiling; and here there is only heat in beit hashchitah, and here only grease on the knife—therefore rinsing suffices. And the Taz wrote another answer: a gentile's knife is different, since he used it frequently and much adhered—therefore it will not be removed by ordinary rinsing. And he wrote further in the Shach in the name of the Bach: because of eiver min hachai one should warn slaughterers to wipe even for birds between slaughter and slaughter (although treifot are not common in them); and wiping with birds' feathers does not help except with something hard such as cloth, or rinsing when cold—see there end of his words, which reconciles the custom of not wiping with birds' feathers. And the Shach disagrees on this and holds rinsing is not required between slaughter and slaughter—see there.`,
  '3#ב': `<b>The slaughterhouse.</b> And the Shach and Taz disagree on this and hold peeling is required; and one should not ask on the Mechaber's view that he ruled rinsing suffices—for in any case rinsing is needed before salting because of blood; and one must say: for blood, ordinary rubbing suffices, but now because of forbidden grease, great rubbing with the hands well is required in order to remove the knife's fat that adhered.`,
  '3#ג': `<b>Hard (ground).</b> The Shach explained: such as he slaughtered many animals and found several among them treifot on inspection—he should no longer slaughter except stick in hard ground and slaughter afterward l'chatchila—Darkei Moshe; and see Peri Chadash, who reconciles the custom of slaughterers who are lenient without sticking their knives. And the Bach wrote: the kosher animals found among them were kashered by the wiping done in the interim; and what helps here—sticking to slaughter afterward l'chatchila—even though with the knife mentioned above sticking does not help l'chatchila, because it absorbed through actual boiling, which is not so here. And if he transgressed and slaughtered without sticking, the Taz wrote he must peel beit hashchitah; and it appears that with three treifah slaughterings combined he is called accustomed to slaughter treifot with it—for with three times there is chazakah, as he wrote in siman 100 seif 4; but l'chatchila wiping well with hair suffices—except Maharshal wrote that now they do not wipe well as appropriate, only casually, and the teacher must warn them about this.`,
});

// --- beer-hagolah ---
patchFile('siman_010/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Statement of Rav Nachman and Rava; and in the Gemara there daf 8. (°) Explanation: that he used it in cutting wood for avodah zarah, as below beginning of siman 139 and siman 142.`,
  '2#_': `Language of the Rambam in chapter 14 of Hilchos Ma'achalot Assurot; and so the Tur here in the name of the Rashba.`,
  '3#_': `Statement there daf 9; and Rav Huna bar bar Chana, Rif, and Rambam there chapter 10.`,
});

// --- beur-hagra ---
patchFile('siman_010/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#א': `<b>New or old, etc.</b> There (in the Gemara).`,
  '1#ב': `<b>That there is no, etc.</b> As he wrote there; and it could be derived, etc.; and learn: that libun (purging by fire) helps—so too other kashering; and as he wrote below that sharpening, etc.; and he relied here on what he wrote below.`,
  '1#ג': `<b>That he sharpened, etc., or, etc.</b> End of Avodah Zarah: the knife's lip, etc., and sticking, etc.; and with a knife, etc.; and as the Rosh explained there—that "or" is taught; and although they said there specifically for eating cold with it, we conclude here that beit hashchitah is cold; and Rashi here, s.v. betzonen, and s.v. vehalachta, etc.; and there is no concern of knife pressure, similar to cutting cold with it.`,
  '1#ד': `<b>And if he slaughtered, etc., and if, etc.</b> Like Rav Huna bar bar Chana—because his words were stated last, according to their way of ruling (except the Rambam in his commentary on the second chapter of Sotah); rather because Rav is greater than him, the Rambam's mind inclined after him somewhat. But Rashi and all the poskim ruled completely like Rav; and so in Darkei Moshe; and this is what the gloss means: and therefore, etc.—meaning by law.`,
  '1#ה': `<b>And in a place of pressure, etc.</b> This refers to what the Shulchan Aruch wrote: that sharpening, etc., is permitted—b'dieved specifically, because some say beit hashchitah is boiling and sticking does not help; and according to some, even sharpening; and as written above in siman 121 seif 7 in the gloss.`,
  '1#ו': `<b>But he should not, etc.</b> Meaning: peeling is forbidden by law according to the gloss; and as written above siman 2 seif 1; and see there siman 69, 96 in the gloss; and if it was used, etc., and if, etc.`,
  '2#א': `<b>(Seif 2) A knife, etc.</b> As he wrote there: the kosher also, etc.; and Tosafot there, s.v. sakin; even though soiled, etc.`,
  '2#ב': `<b>That one rinse it first.</b> Tosafot there, s.v. vehalachta. Explanation: the knife, etc.`,
  '2#ג': `<b>And if, etc.</b> Tosafot Shabbat 42b, s.v. aval. And it appears pouring is not, etc., and a vessel whose use, etc.; and so he says it absorbs only a peel's worth; and the same here—even for Rav, and all the more regarding the knife's absorption from the meat, as Rashi wrote there, s.v. vehalachta, etc.`,
  '3#_': `<b>(Seif 3) He rinses beit hashchitah.</b> Rashi, s.v. betzonen, etc.; and we say there 107b: and if it touches, etc., although, etc.`,
});

// --- kereti ---
patchFile('siman_010/kereti/part-001.txt', 'kereti', {
  '1#א': `New is certainly not forbidden for what was designated for avodah zarah—only "new" means it did not absorb from grease and cooking an avodah zarah offering; only cutting wood for avodah zarah. However, if he cut wood to make an asherah for Canaanites—it is permitted (Peri Chadash in siman 101).`,
  '1#ב': `That there is no defilement of avodah zarah—that they kashered it in a manner that expulsion does not forbid.`,
  '1#ג': `Animal—and the same for a bird, for this too spoils; even though it does not stand for labor; and the proof is that Tosafot challenged from this that it spoils, since we say in Pesachim: slaughter on Shabbat for avodah zarah is called repairing—even though there it speaks of a bird, as above siman 4. And in such a case he brought the view of Damascus Eliezer, who doubts regarding a bird; and there is some room to doubt my proof that I wrote: in general, through shechitah it remains for eating—one could say regarding a bird considered important, he repaired it—what spoilage is here, for it stands only for eating? Unlike an animal, which stands for other things—unlike there with a bird sin-offering forbidden in eating; if so its law equals an animal's; and if for an animal repair from eiver min hachai does not help, so too for a bird one may not slaughter. Nevertheless Tosafot and the poskim who permitted this proof for the Mechaber should be wondered at—and think.`,
  '1#ד': `Spoils—for with avodah zarah we require complete benefit, as written: "it shall not cleave to your hand," etc.; and this is not complete benefit, for his wage comes out in his loss; but regarding spoilage in connection, where we hold on Shabbat one is exempt, we require complete spoilage, not lack of benefit.`,
  '1#ה': `That he sharpened—for the Rambam, sharpening helps like hag'alah; see below siman 122; and even for the Rama who argues below, here regarding shechitah, since in any case many permit, one can say the Rama concedes sharpening helps like hag'alah (Shach).`,
  '1#ו': `Fine—and this means it is known to be ben yomo, for a plain knife is not ben yomo; or grease was smeared on the knife's face—even then not ben yomo, for what is smeared on the knife is not spoiled.`,
  '1#ז': `Nicks—meaning notches; if so, visible grease there, and sticking does not help at all (Shach). And from here one learns it is permitted to slaughter with a knife that has above its edge markings and notches—not like Beit Hillel to declare treifah.`,
  '1#ח': `Rinsing—meaning complete rubbing, and ordinary rinsing does not suffice for blood required in every piece of meat; and if not ben yomo and no fat smeared—see Peleti, who appears even rinsing is not required, only slight rubbing.`,
  '1#ט': `Therefore one should peel it—for most poskim ruled halachah thus, like Rav who said peel; see Peleti, where I gave reason why the Rif ruled rinse, not like Rav.`,
  '1#י': `Permitted l'chatchila—meaning at least by sticking; see Peleti, what he wrote: it is possible to say according to many authors' view that even not in time of pressure, by sticking it is permitted—and all the more in time of pressure.`,
  '1#כ': `He should not slaughter, etc.—and with not ben yomo, Maharshal permits and the Shach questioned to be stringent l'chatchila like the Bach; see Peleti s.k. 2, where I lowered the Rosh's view like Maharshal—and so it is correct.`,
  '2#א': `To slaughter, etc.—even when soiled with blood; regarding blood we say: certainly, since the simanim are busy expelling, they do not absorb—so write the acharonim, and it is simple.`,
  '2#ב': `With it, etc.—and rinsing is not required; see Taz, who brought in the name of the Bach and Hagahat Agudah that rinsing is required because of absorption of eiver min hachai; and the Taz and Peri Chadash are lenient; see Peleti, where I reconciled the Bach's wonder and proof.`,
  '2#ג': `Forbidden to cut boiling with it; and if he koshered by pouring, permitted l'chatchila—so Orach Chaim; and it is correct that Beit Shammai's rejection and knife pressure are no more than pouring.`,
  '2#ד': `Boiling—and if he cut, the Shach's view is b'dieved permitted; and we rely on the view that beit hashchitah is cold—see there, where he elaborated; and therefore permitted l'chatchila to peel. See Peleti, where I wrote the main thing is like Peri Chadash, that peeling is required in any case; and with this, peeling suffices, as appears from the Rashba's words; see Peleti, where I labored greatly to reconcile the Rosh and Tosafot—go read there.`,
  '2#ה': `And permitted to cut cold with it—even sharp things such as radish and the like (Peri Chadash in the name of the Rashba).`,
  '2#ו': `Cold with it—even if he slaughtered many times, since it is because of blood, and blood slides and is slick.`,
  '2#ז': `By rinsing—and from the Rosh's words, who wrote rinsing is not required except for a thick slice, we learn: for the view that rinsing is required, a thick slice does not help; and Maharshal disagrees and sent his hand to emend the Rosh—and the Shach's view is as written. Therefore the Tur did not mention here that a thick slice suffices, as in the later seif; and their reason: they are stringent here and lenient with a treifah knife—the Shach gave the reason that there is also the reason that simanim do not absorb, unlike when cutting cold; and this explanation is strained—for regarding wiping visible on simanim it is not relevant "since busy." Only the reason can be said: kosher slaughter-blood is like water and rinses treifah grease from blood, and it has no power to adhere in beit hashchitah—therefore wiping suffices; see Peleti, where there is another reason to distinguish.`,
  '2#ח': `That one rinse it first—the Taz wrote this unnecessarily, for even if he slaughtered treifah and slaughtered kosher, rinsing helps; and according to what I wrote, there is no difficulty—for kosher blood's rinsing is as explained.`,
  '3#א': `Until one rinses it, etc.—and even with a gentile's knife we hold like Rav who said peel; Rashi answers: there is a difference to absorb in meat, which is soft—forgetting well—unlike expelling from a knife, which is hard, without such power; see Peleti, where I elaborated on these matters at length with several reasons.`,
  '3#ב': `Between each slaughter, etc.—lest a treifah occur; and the Bach wrote: this applies to an animal, where treifot are somewhat common; but for birds, treifot are not common and there is no concern; and what the Bach wrote that there is still concern because of eiver min hachai—the acharonim already disagreed; see Peleti, what he wrote reconciling the Gemara's words—see there.`,
  '3#ג': `He rinses beit hashchitah—so the Tur and acharonim; all challenged: for it was on it visibly from the knife's grease, absorbed, and requires peeling like a gentile's knife; see Peleti, where I argued for the Tur.`,
  '3#ד': `Treifot frequently—and he did not wipe well between slaughter and slaughter (Bach).`,
});

// --- peleti ---
patchFile('siman_010/peleti/part-001.txt', 'peleti', {
  '1#א': `That it spoils—Tosafot challenged: we say in Pesachim one slaughters for avodah zarah on Shabbat—they were concerned about repair, removing it from eiver min hachai; and I did not understand the question: on Shabbat we require spoilage, and this is not spoilage—for what he spoils in shechitah he repairs by permitting from eiver min hachai; but here it is truly not called spoilage; nevertheless it is also not called benefit—for his wage comes out in his loss, and he does not benefit from avodah zarah; so what if it is not spoilage, since he does not benefit? Perhaps this is Tosafot's intent—see there.`,
  '1#ב': `And forbidden to slaughter a dangerously ill animal—if he slaughtered, the Tur brought in the name of the Rosh that such slight benefit is permitted b'dieved; and the Rosh's proof: from what the Gemara asks and could derive from grease prohibition—and it came to teach that all the meat is forbidden; and if because of grease, only the cut place is forbidden; and if it asks on the heter that it is permitted to slaughter with it, etc.—why does it ask? It needed to teach the meat is permitted, and the power of heter is better to teach that although forbidden initially because of grease, nevertheless if he slaughtered it is not forbidden b'dieved, etc. On this Maharsha wondered and wrote: I do not know what he says—for nevertheless it asks well: it is not taught permitted to slaughter and cut, for l'chatchila it is forbidden because of grease even relying that he will peel, lest he forget and not peel, as the Rosh himself wrote. And I did not merit to understand Maharsha's words; and one must explain their words: why did they not briefly ask—should it not be permitted to slaughter relying that he will peel? Nevertheless for the Rosh's difficulty there is no answer, for there is no prohibition b'dieved; and it teaches that for spoilage l'chatchila it is permitted from doubt—what does it challenge and derive from grease prohibition? We know that for grease it is known permitted l'chatchila to slaughter relying on peeling; but if because of avodah zarah benefit it is forbidden, it teaches spoilage; if so, it should have challenged the Rosh either way. And one can say: granted, if permitted—as taught, the main intent is the animal is permitted and was not forbidden like a dangerously ill animal—it is not difficult because of grease, for there the prohibition is only a peel's worth, and the language "permitted" nevertheless is fine: even because of grease, permitted l'chatchila to slaughter relying he will peel; and if it is difficult how it teaches plainly permitted, implying even without peeling—say the intent is to permit the animal; whether he must slaughter relying on peeling is not discussed; but if b'dieved it is permitted in any case, the whole intent of "permitted" is to instruct he may slaughter l'chatchila without delay—it is difficult, for there is grease; in any case it should say he must slaughter on condition he will peel, for all his intent is initial permissibility. And for this intent one can say in the Rosh's words: as the Rosh wrote explicitly—what we say "slaughters with a gentile's knife, peel" means where it is known to be ben yomo; otherwise a plain gentile vessel is not ben yomo and would be permitted without anything. Accordingly one can say: why does the Gemara ask and derive from grease—and it needed to push with a forced change, cutting wood or building a brick, to say it speaks of a plain knife that is not ben yomo and would be permitted, and even if we say a plain knife has grease smeared—we could say wiping; and why need a brick, and all the more the Rosh does not hold fat is smeared on the face. And thus the Gemara's difficulty is l'chatchila: l'chatchila forbidden, and l'chatchila forbidden to slaughter because of grease. And the Rosh's claim is correct: nevertheless it teaches because of benefit of avodah zarah utensils—for because of this grease, permitted l'chatchila to slaughter relying he will later throw away enough for the absorbed peel from grease—and it is not relevant "lest he forget and not peel"—what of it, there is no Torah prohibition, and if he eats without peeling he does not violate a Torah prohibition of noten taam lifgam, which is permitted; and one may rely on this and the question is fine. Unlike below with a ben yomo knife, where it is fine to forbid slaughter relying on peeling afterward, lest he forget and violate a Torah prohibition. And one can understand in the Rosh why he began with the difficulty "and derive from grease"—it refers to forbidding slaughter of a dangerously ill animal, not immediately as Rashi truly explained that the difficulty refers to permitting spoilage; see Maharsha. And it is possible the Rosh holds: Rav's "peel" with a gentile knife—one can say as Semag: Rav's reason is noten taam lifgam is forbidden. Accordingly one can ask: why does the Gemara ask and derive from grease—perhaps Rav only says peel because Rav holds noten taam lifgam is forbidden and they were stringent like Beit Shammai; but for us, who hold noten taam lifgam is permitted, only l'chatchila forbidden—they are not so stringent with heat in beit hashchitah; and if it says regarding avodah zarah: how does Rav hold, whether noten taam lifgam is permitted or forbidden—perhaps his doubt, and for Rava Rav Nachman is clear that Rav holds noten taam lifgam is forbidden—and so Rashi must say in Pesachim daf 46; therefore there is no proof from "peel"; therefore the Rosh explained the Gemara's difficulty "and derive" refers to the dangerously ill animal case—and this is what Rava says, and Rava is uncertain how Rav holds regarding noten taam lifgam—see there. And from this it appears the Rambam, who rules not like the Rosh, because he holds as I wrote in laws of meat and milk: therefore noten taam lifgam is permitted because it is not in the manner of their benefit; but for avodah zarah, even not in the manner of their benefit, possibly forbidden, as Tosafot Pesachim 26, s.v. she'ani heikhal, and Avodah Zarah 43, s.v. amru lo. If so, even noten taam lifgam is forbidden, and the Gemara asks and derives well, etc.; and the Rosh's proof and the Rambam's words are correct.`,
  '1#ג': `Repairs—and the Shach's view: even the Rosh concedes at least knife-wage benefit must be given; and Peri Chadash challenged him: the Rosh's view regarding bread baked in an oven—all is forbidden—is not understood in his words, for the Rosh distinguishes bread benefit from knife benefit; and the Shach holds the distinction is we require only knife-wage benefit to slaughter—if so, what proof from bread? Indeed it is difficult: still the Gemara asks "and derive," etc.—peeling suffices; therefore knife-wage benefit is needed; and for a dangerously ill animal where knife-wage is expensive, much must be given—rather we learn the Sages did not penalize in this. And were I not afraid they would laugh at me in the study hall, I would say: this "to eat through shechitah" is a mitzvah—"and you shall slaughter" not "and you shall stab" as in the desert; we were only commanded the mitzvah of shechitah, and so we bless; if so, mitzvot given to enjoy are like lulav and similar, permitted in an asherah. With this one can resolve the Rif's words, who omitted the entire statement regarding an avodah zarah knife—and they wondered why. According to what I said it is fine: he holds mitzvot given to enjoy were given; but according to what we hold, mitzvot were not given to enjoy—all this is void.`,
  '1#ד': `He rinses beit hashchitah—this is the Rambam's ruling, like the Rif, who rules not like Rav who said peel; and they already wondered why he ruled like Ravah in place of Rav. And if we hold with a knife that slaughtered treifah in cold—as they wrote, the printers' error—and truly their error is compelled: if one law applies to a gentile knife for slaughtering treifah, why did Rav and Ravah establish their dispute on a gentile knife, and R' Elazar and Ravina on a knife that slaughtered treifah, and not state their words in one manner? And furthermore, do R' Elazar and Ravina argue in Rav and Ravah's dispute—what do they argue? Let it teach the halachah follows Rav or Ravah! And it is strained to say both argue according to Ravah, that rinse—Rav's colleague holds nevertheless there, after he slaughtered; but here l'chatchila to slaughter another animal with it, Rav's colleague holds in hot—this is strained; and also the Gemara's challenge: every animal has eiver min hachai for R' Elazar's colleague, and it does not ask Rav, who holds peel—if so, every animal absorbed eiver min hachai and the knife needs hag'alah. Rather we learn there is room for the printers' error; and it appears to me to distinguish between "peel" and treifah knife—and then the difficulty on the Rif is in place: why he ruled like Rav. From Semag negative commandment 37 it appears the reason is noten taam lifgam, and Rav forbids in such a case noten taam lifgam. And this does not suffice for the Rambam—for the Rambam wrote: if he peeled, this is praiseworthy; shall he say so in noten taam lifgam laws, where the stringent is praiseworthy? It is strained to say it speaks of grease smeared on its back, and the Rambam according to his view that even smearing on the surface becomes noten taam lifgam, as explained there in Hilchos Ma'achalot Assurot chapter 16; nevertheless his view is good to peel, for visible grease is here—and all this is strained. But in the Rif one can seemingly say: therefore he ruled not like Rav, who holds Rav for his reason that noten taam lifgam is forbidden. But it is difficult: whence for the Gemara to say Rav and Ravah argue whether beit hashchitah is cold or hot—say they argue whether noten taam lifgam in such a case is forbidden or permitted! Granted for Rashi in Pesachim daf 46, for his reason, s.v., who wrote Ravah holds noten taam lifgam forbidden—see there in Tosafot, s.v. amar rav, why we do not establish Rav and Rava's dispute on this. One can say: otherwise Ravah, who holds noten taam lifgam requires rinsing for all, would establish Rav and Ravah's dispute on ben yomo—whether noten taam lifgam is permitted or forbidden; or the Gemara's question is difficult to establish the dispute thus. On the contrary, Rashi's proof that he rules like Rav is from the difficulty: halachah follows Rav—and then difficult halachah against halachah, for we hold noten taam lifgam is permitted; therefore the Gemara establishes the dispute elsewhere, and it speaks of ben yomo, as Tosafot wrote. But for the Rif it is difficult—and strained to say he holds if they argue about noten taam lifgam they argue in general; or even Ravah holds noten taam lifgam forbidden and holds nevertheless rinse; and truly one can say: since we hold noten taam lifgam permitted, rinsing is also not required—only the Rif was stringent—and think. But truly I did not know the wonder: did not the Rashba cry out: how can beit hashchitah be hotter than kli sheni heat, which does not cook—and from this he was compelled to say kli sheni absorbs and expels in any case? But the Shulchan Aruch below simanim 68 and 105 does not hold thus—the difficulty is in place; and Peri Chadash in siman 68 wrote: indeed it is difficult for the view that therefore peel is because beit hashchitah is hot; but for the view of knife pressure—and truly this too is strained, that knife pressure would absorb more than kli sheni heat. And even if we say like Beit Shammai—what shall we say in what most authors wrote? See below those simanim regarding metal vessels: even kli rishon does not cook (and according to Rabbenu Tam and Rosh it cooks and absorbs everything as one) until fire passes beneath it; and shall heat in beit hashchitah be more than kli rishon heat, without fire passing beneath—and therefore the Rif holds everything reverts to those views in Yerushalmi chapter Kirah and Ma'aser Sheni, that kli sheni or pouring cooks even in copper vessels, and equals other matters; but according to our conclusion there, in metal vessels even kli rishon does not help to absorb—how can heat in beit hashchitah act to expel from a shechitah knife's absorption and require peeling? Therefore he ruled halachah not like Rav, and only rinsing is needed. And it is possible to distinguish: kli sheni heat comes elsewhere incidentally, and all the more if it will stand and cool—therefore it lacks power to absorb; but heat in beit hashchitah has heat in its essence, for the bloods boil and have power to absorb. Nevertheless, that even kli rishon does not cook until fire passes beneath is difficult: if its power is not as good as beit hashchitah or knife pressure—and I said in my novellae: it is proved there is not so much heat in beit hashchitah—for otherwise how do we slaughter the Pesach? The shechitah knife heats beit hashchitah, and afterward the knife is spun for peeling beit hashchitah—and spinning is because of meat; see Pesachim: a drop fell from its gravy, etc.—Tosafot challenged thus regarding a spit; and thus it is not hot, only for Rav who holds "upper man"—if so, the knife is not heated at all and not spun for Pesach, as appears there in the above view; and fine to say beit hashchitah heat is strong. Therefore Rav holds peel; if so, for us who hold "lower man," there is none—proved there is no hot beit hashchitah; therefore he ruled rinse—and think. And truly it is correct and clear: although peeling is required, he holds only stringently that the rabbis were stringent—and therefore there is no proof for beit hashchitah, for rabbinic decree there is no difficulty or comparison; and if so, in any case rabbinic decree, and in a place of doubt we are lenient—no place to be stringent.`,
  '1#ה': `In a place of pressure, etc.—and if he stuck in the ground or rinsed the knife so there is no visible grease, and the knife is ben yomo: the Rashba's view—nothing is needed, for there is no heat in beit hashchitah to expel anything from the hard knife (and this is somewhat as I wrote regarding metal vessels requiring fire beneath). So the Bach for the Rashba's view, and so Peri Chadash—and not like the Shach on the Rashba; the investigator in Tur Orach Chaim will find this explicitly, and elaboration here is unnecessary. However, the Mordechai at the beginning of the first chapter of Chullin holds: specifically when not ben yomo, sticking suffices; but for ben yomo, sticking does not help and hag'alah is required. And in Tosafot Chullin 8, s.v. shelivnah, who wrote: therefore with an avodah zarah knife a brick is required, and sticking does not suffice—in order to reconcile even if beit hashchitah is boiling. And if Tosafot held like the Mordechai, the rule should require peeling and sticking should not help—they should have said briefly: the Gemara comes according to the conclusion that hag'alah is required and sticking does not help—what difference if beit hashchitah is boiling or cold, finally sticking does not help by law, and shall the Gemara be against halachah? Rather Tosafot clearly hold: since we hold halachah like Ravina in cold because beit hashchitah is cold, as Rashi wrote explicitly—only sticking is needed, for beit hashchitah does not absorb or expel the knife's absorption; if so, even with that avodah zarah knife, sticking suffices; therefore Tosafot wrote a brick is needed to reconcile even for one who holds beit hashchitah is boiling—namely R' Elazar's colleague, who holds hot; and this is also resolved according to him, and for his view sticking does not help. And if so, it is proved Tosafot do not hold like the Mordechai, only according to what we hold like Ravina, sticking suffices, as the Rashba's view. And Rashi wrote, s.v. vehalachta: even in cold regarding a permitted knife he ruled halachah for the permitted side, that it is not forbidden from this absorption, and it is hard to absorb except through boiling; but regarding a forbidden gentile knife, in the earlier dispute he did not rule, because the knife and meat are soft to absorb, end of his words. And so the Rosh wrote there; and thus according to the plain meaning: Rav forbids because the meat is soft and absorbs forbidden grease; but in Ravina's matter, where the knife absorbs treifah through heat in beit hashchitah, and likewise in second shechitah beit hashchitah expels from the hard knife—we do not say so. And so the Rashba wrote: and if so, with a gentile knife that was stuck or wiped well, there is no concern of grease on the surface, only from absorption in the knife—heat in beit hashchitah has no power to expel and re-absorb; sticking helps and hag'alah is not required. These are exactly Rashba's words, following Rashi. Indeed in the Rosh's words one can wonder: the above Rashi holds like the Rashba regarding a gentile knife with grease smeared on its face, therefore peeling is required, for beit hashchitah absorbs forbidden grease into soft meat. But the Rosh, who wrote a gentile knife speaks where known ben yomo—otherwise it would be noten taam lifgam and permitted—we learn he does not hold grease on the surface; if so, there is no absorption and expulsion in beit hashchitah, and here the knife is hard—and strained to divide between absorption and expulsion, for the rule is: as it absorbs, so it expels; and why should the Rosh hold: even though grease is smeared, nevertheless if the knife is not ben yomo, even smeared grease is spoiled, as the Rambam and his support hold—for the Tur siman 128 wrote without any dispute that visible matter is not spoiled; and if his father disagreed, how plain against his view? And it is clear this is the Rosh's view: we are not concerned that fat is smeared on the face, as appears from his words; if so, the difficulty is in place. And truly we must be precise in Rashi: if Rashi's intent is only to distinguish Rav from Ravina, as appears from the Rashba—there soft matter and in Ravina hard knife—why did Rashi always mention forbidden and permitted language, saying regarding a permitted knife he ruled halachah for the permitted side, etc., but regarding a forbidden gentile knife in the earlier matter he did not rule because knife and meat are soft to absorb—what did Rashi seek here? Forbidden or permitted—all depends on soft and hard; and if permitted is also soft, peel. And it appears certainly besides soft/hard distinction, there is a broad distinction between Rav and Ravina: certainly through heat in beit hashchitah the knife absorbs or expels a slight thing, for knife pressure or pressure is not great; therefore with a knife that is inherently permitted, only that he slaughtered treifah with it and it absorbed slightly through heat in beit hashchitah, and afterward when slaughtering another animal, heat in beit hashchitah expels from this second slight matter—it is a small of a small and we are not concerned. But with a forbidden gentile knife with much absorption—even if beit hashchitah expels only slightly, there is still a small amount and peeling is required. Therefore also with a knife with which he cut boiling, it is forbidden and requires peeling—for although the knife absorbed only slightly, this slight matter is expelled explicitly to boiling and forbids. And this explanation you will find the faith of these words almost in the Rashba's and Razah's novellae. Therefore Rashi may have intended: why he precisely distinguished forbidden from permitted—look and you will see as words only seemingly difficult; therefore it appears certainly the Gemara's plain gentile knife speaks of ben yomo, as Tosafot and Rosh wrote, or of not ben yomo only not wiped and grease smeared on it. In every case Rav speaks, and for that case where it is not ben yomo and we judge because of smeared grease—there is no distinction between forbidden and permitted, for smearing itself is a slight visible matter, as all poskim wrote; if so, if beit hashchitah's heat does not expel and absorb only slightly, it is still a small of a small and still difficult to permit—therefore we distinguish soft from hard: with soft, beit hashchitah absorbs more—therefore with a gentile treifah knife. This is in that case; but in another case, not Rav's smearing matter, only ben yomo knife—there is no soft/hard distinction, for heat in beit hashchitah is needed to expel the knife's absorption for Rav. And one must say the second answer: although it is hard and beit hashchitah absorbs only slightly—what of it, the knife was forbidden beforehand and its absorption is much, unlike a treifah knife that absorbed only slightly; therefore heat in beit hashchitah does not expel from hard either except slightly—and it is a small of a small, and we are not so stringent—and think. And it is precisely analyzed in Rashi's language—and if the Rosh wrote: with a knife that slaughtered, forbidden to cut boiling without hag'alah, even though he ruled there is no heat in beit hashchitah controlling the hard knife—for according to the one who says beit hashchitah is boiling, even for Ravina, and since there is some absorption, the boiling cut afterward fully absorbs and forbids (and what he wrote below for the one who says cold, etc., I will write in the next s.k.)—if so, it is clarified for us: with a ben yomo knife, even clean of smeared fat, nevertheless heat in beit hashchitah expels slightly into the slaughtered animal, even though the knife is hard, and peeling is required, not sticking—and this is the Mordechai's view above; nevertheless one may be lenient, since in any case the Rif and Rambam rule not like Rav and Rashba, and Tosafot permit sticking—one may rely.`,
  '2#א': `Permitted to slaughter, etc.—the Bach brought in Hagahat Agudah to require rinsing because of eiver min hachai—for the Gemara challenged for the one who says in hot: why is treifah different, that it absorbs prohibition—for kosher also absorbed eiver min hachai, and the knife should require hag'alah. It did not challenge for the one who says cold: kosher also should require rinsing because it absorbed eiver min hachai. Rather we learn the true law requires rinsing; and Peri Chadash wrote the Rashba already stood on this difficulty. And to me it appears simply: certainly the Gemara knew—even according to the one who says once the majority is cut there is no longer eiver min hachai—it holds that beforehand it is also hot and absorbs; therefore for the one who says cold, rinsing helps to remove adhering grease; therefore a thick slice helps; if so, when he begins slaughter and grease of eiver min hachai adheres when reaching slaughter of the majority, when there is no longer eiver min hachai—then through shechitah in heat and knife pressure, the adhering eiver min hachai grease is fixed through slaughter of simanim that have no eiver min hachai, and spurting blood washes it. And there is no difficulty; but for the one who says hot, with full absorption, it fine asks: only hag'alah in boiling helps, and shechitah of the majority and absorption of eiver min hachai remain in the knife and do not leave through shechitah afterward—and think.`,
  '2#ב': `To cut boiling with it; and if he cut, the Tur did not explain whether forbidden entirely, or peeling, or kosher by rinsing the boiling thing cut with such a knife. To clarify, we copy the Rosh in chapter Kol HaBasar daf 102b: Rav Nachman said Shmuel said: a knife with which he slaughtered—forbidden to cut boiling with it; cold—some say rinsing required, some say not, except for a thick slice; and Rashi: forbidden to cut because beit hashchitah boiling absorbs the knife from blood, and forbidden to cut boiling because it returns and expels in it, end of his words. And the Rosh in chapter 25 wrote: forbidden to cut boiling; and the one above who says beit hashchitah is boiling requires hag'alah; and for the one who says cold, rinsing suffices. And in the first chapter of Chullin, after writing halachah like Ravina in cold and distinguishing gentile knife from treifah knife, he wrote: and Ravina's dispute is for slaughtering with them; but to cut boiling, even if he slaughtered kosher, we say in chapter 25: a knife with which he slaughtered—forbidden to cut boiling, even if he rinsed it—for even to cut cold, some say rinsing required, some say not, and the knife is the subject, end of his words. Here there are three contradictions: here, although he ruled like Ravina in cold, he ruled cutting boiling requires hag'alah—and Tosafot proved this, since in cold rinsing is required and the knife is the subject, we learn boiling requires hag'alah; and in chapter 25 he wrote for the one who says beit hashchitah cold—and this is Ravina—even cutting boiling, rinsing suffices by law like Ravina. If so, the matters contradict; and also where did the Rosh's proof go—if by rinsing, what difference between cutting boiling and cutting cold? And more wonder on the hints, who ruled cutting boiling requires hag'alah—according to the Rosh's premise for Ravina, who holds like me, rinsing suffices. The Shach sought to say: for the one who says beit hashchitah cold, rinsing is required if he already slaughtered and cut—b'dieved; but l'chatchila to cut with it, Ravina concedes hag'alah is required; and that cold suffices for slaughtering treifah is b'dieved to kosher the knife between treifah and kosher slaughter—this is the root of his words. And the Peri Chadash already rejected this—we do not find this reasoning in authors, and the Rosh's language cannot bear it at all. In my humble view, one could say briefly: Ravina concedes to Rav who said peel—not to slaughter with a gentile knife; unlike one slaughtering treifah—what shall he do, kosher between each slaughter? Therefore they were lenient. And so what Tosafot inferred: why does rinsing suffice and sticking is not required—answer: here it is like b'dieved, and he always sticks the knife ten times in hard ground. And what I wrote here can be understood per Maharsha there, s.v. sakin treifah, etc., who wrote Tosafot: to slaughter after slaughtering kosher—all agree permitted even for R' Elazar's colleague; but to cut boiling forbidden; and Maharsha wrote: it appears even the one who says here cold holds cutting boiling requires hag'alah—meaning he holds beit hashchitah is hot only because simanim are busy expelling and do not absorb—and this does not apply to boiling. Maharsha himself stood: Tosafot's answer that therefore sticking is not required is because beit hashchitah is cold—yet below boiling is required—see there. And it appears without this we can infer in Tosafot: why do they seek this—for Rav Elazar's colleague, slaughtering kosher is permitted in any case, but cutting boiling is forbidden—what difference to Tosafot for Rav Elazar's colleague, halachah is as he holds, and enough that Tosafot wrote so for Ravina, etc.—nevertheless cutting boiling is forbidden for the reason Maharsha wrote, as Tosafot prove through hag'alah—for otherwise what difference between cold and hot? Therefore cutting boiling requires hag'alah; but also in the above Rosh in chapter 25, who wrote for the one who says beit hashchitah hot—in hot, what did he seek from this? Halachah should stand like Ravina! And how could he think for the one who says cold, rinsing—proved from cold rinse that it does not exist? Rather the Rosh holds what the Gemara says: cold—some say rinsing required, some say not—who are they disputing, and what is their nature? To say Shmuel's words—Shmuel spoke only of boiling; but the Rosh holds Shmuel said plainly forbidden to cut boiling, and if he cut, Shmuel did not explain the law, did not enter the dispute—relied on the dispute of R' Elazar and Ravina, as the Rosh wrote: for this in hot, for this in cold; and therefore the Gemara says in cold "they said to him"—R' Elazar, who holds beit hashchitah boiling—if so, cutting boiling requires hag'alah; if so, cutting cold requires rinsing, one degree down; "they said to him"—Ravina, who holds beit hashchitah cold—if so, even cutting boiling requires only rinsing; if so, cutting cold requires no rinsing at all—and think. And if so, the Rosh wrote well: for the one who says cold, rinsing suffices—and no difficulty: cold requires rinsing, meaning for Ravina rinsing is not required. These are the disputants in the Gemara. This is clear and aims at truth's center. Tosafot's intent also revolves around this: they did not seek to infer that for Ravina, after kosher slaughter, he may slaughter again, yet cutting boiling is forbidden—this is not because Ravina truly requires hag'alah even for cutting boiling; rather they inferred on R' Elazar's colleague, who concedes permitted to slaughter if he slaughtered kosher, yet forbidden to cut boiling—as proved from "they said" regarding cold requiring rinsing, we learn boiling requires hag'alah—they inferred well and distinguished "since simanim are busy," etc. Also Tosafot's difficulty in the next statement, inferring cold requires rinsing, therefore boiling requires hag'alah—therefore even if beit hashchitah is boiling, cold suffices by rinsing and sticking is not needed—as Maharshal questioned. And it appears without this we can infer in Tosafot: why seek this—for Rav Elazar's colleague permitted in any case, yet forbidden to cut boiling—what difference? Halachah as he holds is enough Tosafot wrote for Ravina; nevertheless cutting boiling forbidden, etc. Also the next Tosafot difficulty: inferring cold requires rinsing, therefore boiling requires hag'alah—therefore even if beit hashchitah boiling, cold by rinsing, not sticking—as Maharshal questioned. It appears without this we can infer: why seek—for Ravina permitted in any case, yet cutting boiling forbidden—not because Ravina requires hag'alah for cutting boiling; rather inferred on R' Elazar's colleague from "they said" cold requires rinsing, we learn boiling requires hag'alah. They inferred well, distinguished simanim busy, etc. Also Tosafot's next difficulty on inferring cold requires rinsing therefore boiling hag'alah—even if beit hashchitah boiling, cold by rinsing without sticking—as Maharshal questioned. It appears Tosafot did not want in this discourse to descend into commentators' disputes; they took a short way: for R' Elazar's colleague certainly—and so Maharsha explains Tosafot hold beit hashchitah is hot. Therefore truth guides a spacious path for all without doubt: law as I wrote—not like the Shach, that if he cut, in any case peeling is required.`,
  '3#א': `Until one rinses it when cold—for we ruled above with a gentile knife like Rav who said peel, requiring peeling, as I explained what Rashi wrote and Be'ur Rosh's words and what difference cutting boiling has. And truly in my humble view in Tosafot one can say simply and think: all the reasoning that beit hashchitah is boiling or knife pressure absorbs and expels is one opinion, not decided whether it expels and how much—much or little—or nullified in a small amount. If so, general rule for us: in min b'aino mino it is forbidden from the Torah and poured until the measure cannot stand; and treifah doubt is Torah stringency; and in min b'mino it is kosher, rabbinic doubt lenient. If so, slaughtering with a treifah knife—even if it absorbed kosher treifah grease—it is min b'mino, and we doubt whether it absorbed; plainly kosher, rabbinic doubt. But with a gentile knife—if it absorbs, it is min b'aino mino, doubt stringently, law with Rav who peels—and think. Therefore with a knife that slaughtered and blood is on it and he slaughtered boiling—it is min b'aino mino, blood in other things—even Ravina concedes hag'alah is required—and think. With this one can explain Tosafot on a gentile knife: known ben yomo—and not as the Rosh's printers in Avodah Zarah chapter 2, noten taam lifgam forbidden l'chatchila (and one can explain the Rosh's words: even though he used "after he did," for Rav who holds noten taam lifgam forbidden; the Gemara bringing the dispute, although we hold noten taam lifgam permitted, is because of l'chatchila). If so, this is rabbinically forbidden, not the law of peel—and think. All is reconciled: the Rosh's view that wiping a thick slice does not help when cutting cold with a knife that slaughtered, and we hold wiping helps when slaughtering treifah; see Shach and Kereti s.k. 18—according to what I said: slaughtering treifah is min b'mino, cutting cold min b'aino mino—they were stringent. Rashi, who did not answer so, goes to his view that min b'mino is not nullified by sixty, and min b'aino mino rabbinic—taste is not like essence, not Torah. But since we do not hold thus, the matter is correct and clear. And one can say: nevertheless difficult from that he slaughtered with it, forbidden to cut boiling—and if it is min b'aino mino and Torah, all boiling concern applies; and absorbed blood is cooked or roasted blood from the Torah permitted—its law equals min b'mino. Truth in my novellae: one can say what is taught forbidden to cut boiling, and if he cut, rinsing suffices, and what is taught cold requires rinsing—cold is stricter than boiling; and if hypothetically he cut an apple and blood is visible from the knife, he is pressed—this is eating Torah prohibition; but if it adhered to something boiling, in that boiling thing which is boiling kli rishon it cooked—and cooked blood is rabbinic—here rabbinic doubt. In my humble view this answer suffices greatly. With this also what all acharonim strongly challenged on the Tur—if he did not rinse when slaughtering treifah, he rinses beit hashchitah afterward—for it is no worse than a gentile knife where we hold peel—is fine according to what I said: if treifah grease adhered to the knife and from there to kosher animal, it is doubt and min b'mino, like noten taam lifgam and kosher; unlike a gentile knife, min b'aino mino, Torah doubt stringently.`,
  '3#ב': `And if accustomed—this is Tosafot's answer: why does avodah zarah require sticking here and not? Answer: here it is only by chance. Therefore he ruled: if accustomed, sticking is required. But Rabbeinu Tam divides another way: here absorption is in cold, and avodah zarah absorbs in hot; and Tosafot challenged from Shmuel's knife, etc., we learn he holds beit hashchitah boiling—nevertheless in cold they said rinsing required; answer: blood is different, it slides slick. The Mechaber ruled like Tosafot, not Rabbeinu Tam; therefore he distinguishes accustomed from chance in general. If so, we learn he does not hold Rabbeinu Tam's view to distinguish blood that slides from other things—and if so, difficult above seif 2 with a knife that slaughtered: he does not distinguish chance from accustomed, never requires sticking—and we were because blood slides, Rabbeinu Tam's answer that Tosafot do not hold; if so, difficult against itself. The Shach in s.k. 15 gave the reason blood slides and did not notice this is only according to Rabbeinu Tam—but Tosafot do not hold. Strained to say: he knew blood slides acts so it does not adhere much—even many slaughterings, it is like slaughtering by chance; but regarding not needing sticking at all and use through cold, Tosafot do not distinguish—and this is strained. More likely: sticking in the ground acts in two aspects—if thereby everything adhering with ultimate adhesion on the knife is removed, so even the outer thin peel peeled falls off in sticking (see Shach s.k. 7). If we come to judgment on what adheres on the knife's face, certainly distinguish blood from other things—for blood is scraped and slick, no adhesion at all, as the Ra'ah wrote there daf 16. But if we say it is nevertheless absorbed into such a thin outer peel, hard to say blood is scraped, etc.; and conversely, if to remove the peel, there is difference between absorption in hot and in cold—as understood, Rabbeinu Tam's view; but if what adheres externally on the knife's face—what difference hot from cold? If so, certainly Tosafot do not distinguish hot from cold—and they hold sticking certainly removes what is smeared on the knife's face, and certainly distinguish blood from other things—and think. But for Rabbeinu Tam, who distinguishes absorption in hot from cold, and therefore holds the thin outer peel absorbs—and in this Tosafot do not distinguish blood, for according to them it slides slick—therefore they challenged him from a knife that slaughtered blood, and Rabbeinu Tam answers: nevertheless we say this reasoning, and infer cold blood does not absorb so much—indeed he inferred it does not absorb—and therefore the Shach's words are correct: for all we say this reasoning blood slides slick—and think.`,
});

// --- pitchei-teshuva, rabbi-akiva-eiger-yd, yad-avraham, yad-ephraim, nekudot-hakesef, kaf-hachayim ---
patchFile('siman_010/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>To slaughter with it a dangerously ill animal.</b> See responsum Penei Aryeh siman 65 in the middle of the answer, who wrote: it is not specifically slaughter, but even stabbing a dangerously ill animal with such a knife to sell the meat to a gentile is also forbidden—see there; and see what he wrote below siman 117 s.k. 5 in his name. And see there in siman 66, who wrote it is permitted to pierce meat of veins of fat and blood with a gentile's knife; and see what he wrote from this below siman 121 s.k. 4.`,
  '2#_': `<b>On his (sharpening wheel).</b> Avodat HaGershuni: on a knife, not being ben yomo does not help; and see responsum Perach Mateh Aharon part 2 end of siman 47, who wrote: this is only where they are not accustomed to clean knives well; but we, whose way is to clean well, are certainly permitted—see there. And see responsum Chut HaShani siman 55, who wrote regarding cutting on Pesach with a chametz knife: even if he says it was wiped, he is not believed—for we say an unfounded matter, etc.; and see what he wrote below siman 94 s.k. 1 in the name of Noda BiYehudah.`,
  '3#_': `<b>This is praiseworthy (peeling).</b> See Taz and Shach, who challenged: from law, peeling is required; and see responsum Beit Shmuel Acharon part 4 siman 8.`,
});

patchFile('siman_010/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 10 seif 1) <b>And forbidden</b> to slaughter with it a dangerously ill animal. And regarding b'dieved see Shach; and it is difficult for me to say: since benefit is forbidden, it is included in "you shall not do"—and if he did, it does not help, and it is as if not slaughtered. Granted for another's animal for avodah zarah, where most poskim hold for the view "there is no benefit from a companion" (ein hana'ah l'chavero)—permitted even in eating—here there is no difficulty to say b'dieved it does not help, for the transgression does not depend specifically on shechitah—for even if he stabs for avodah zarah there is a transgression; if so, why say b'dieved it does not help—for nevertheless stabbing is before you and the transgression was done and cannot be fixed by "it does not help." And why do I say it is not difficult what Mahari"t challenged in his responsum on the mishnah: one who slaughters on Shabbat—his shechitah is valid—shall we say b'dieved it does not help? For there too the transgression is not because of shechitah but because of taking a soul, and it is repair to remove from eiver min hachai status—in this "it does not help" is not relevant, for it died before you and the eiver min hachai prohibition ceased. But here, slaughtering a dangerously ill animal with an avodah zarah knife—the transgression is that he benefits from avodah zarah so the animal not die; and if we judge the shechitah does not help and it is as if it died by itself and like ordinary stabbing—he benefits nothing from the knife; and especially according to what the Tur in Rosh Hashanah (daf 25) wrote regarding blowing a shofar of an olah: even for the view "after the fact it helps," that is in general—for even if the law were it does not help, nevertheless he committed a transgression violating the Merciful One's statement; but with a shofar of an olah, the benefit is fulfillment of the mitzvah, and if he does not fulfill, he neither benefits nor violates the Merciful One's statement—in this all agree it does not help—see there. And if so here slaughtering a dangerously ill animal, we should also say it does not help and he violated nothing—and think. What Peleti wrote to judge regarding shechitah: since shechitah is a mitzvah matter—not to eat meat it dies—is included in "mitzvot were not given for benefit," as explained in Eruvin 31a: an eruv in benefit prohibition depends—if they make an eruv only for a mitzvah matter, it is included in mitzvot were not given for benefit; but if they make an eruv for a permitted matter, only that going without an eruv is forbidden—and if so, to save him from that prohibition and nevertheless it is called benefit—and similarly shechitah, since they slaughter for a permitted matter.`,
  '2#_': `(Shach s.k. 6) <b>There is power in the heat of beit hashchitah to expel what is in the knife's peel.</b> This is astonishing—for if so, when slaughtering with a treifah knife, why does rinsing help? For the Rashba—the knife absorbed, only it does not expel with heat in beit hashchitah—yet nevertheless it absorbed what is in the knife's peel; and I would have said per the Rashba in Ma'adanei Yom Tov daf 73: their dispute regarding a knife with which he slaughtered kosher—some say rinsing required, some say not, only wiping—meaning certainly good wiping removes what is visible from the knife; and therefore there is an opinion it helps, for in cold pressure does not expel at all; and the one who requires rinsing holds that because of pressure it expels even in cold, and rinsing the knife is to expel absorption from the knife so it not expel afterward when cutting cold—see there. And that with a knife mentioned, even for cold sticking is required—since the absorption in hot joined, rinsing does not expel it and it expels afterward when cutting cold through pressure; if so, apparently the Shach's words are correct: in cold beit hashchitah regarding not expelling from the knife, nevertheless it is no worse than ordinary cold, that through knife pressure it expels slightly from the knife; and since it expels, the simanim absorb that slight amount up to a peel's worth—for regarding absorption we say through slight boiling in beit hashchitah it absorbs from the visible up to a peel's worth; if so, what difference whether it absorbs the visible itself or what was expelled from the knife? Therefore with a knife mentioned, where rinsing does not expel at all from the knife until afterward cutting cold expels greatly through pressure—therefore if he slaughtered without sticking, peeling is required; but with a treifah knife, absorbed in the knife not through hot, and rinsing helps to expel slightly from the knife until afterward the knife does not expel further when cutting cold—likewise it does not expel in shechitah, like cold. With this the Shach's words in s.k. 17 are also resolved: he concludes specifically here wiping helps for slaughtering with it, but not in general—and seemingly contradicts his own words (siman 91 s.k. 3) that wiping is like rinsing. According to the above it is fine: in general, where there is also pressure as in shechitah, wiping does not help; only in shechitah because simanim are busy. In siman 91, which speaks without pressure, wiping helps. <b>However</b> it still does not suffice—for ultimately why does wiping help with a treifah knife? Wiping only removes the visible, and when he slaughters afterward, through pressure it expels from the knife's peel—and one must say: in beit hashchitah, since busy, it does not absorb that slight amount; if so, with a knife mentioned, why without sticking is peeling required—the simanim did not absorb the slight amount in the knife's peel? And if with a knife mentioned rinsing does not help, with a treifah knife wiping should not help either—and we must say and distinguish: busy helps only with a treifah knife regarding absorption in the knife's peel that was not absorbed through hot—in this busy helps; but with a knife mentioned there is much absorption in the knife's peel, busy does not help—and still think.`,
  '3#_': `(Be'er Heitev) <b>However in the Mordechai first chapter of Chullin it appears even sticking does not help.</b> And that with a treifah knife rinsing helps—must say either as Rashi wrote, the knife is hard to absorb, and therefore one can say it expels through heat in beit hashchitah; or that it absorbed much—namely with an avodah zarah knife it expels through heat in beit hashchitah, but with a knife that slaughtered treifah, absorbed through beit hashchitah is slight absorption and does not expel with heat in beit hashchitah. And what Tosafot Beit Shmuel wrote—that this is Tosafot's view from s.v. kegon shelivnah, etc., and that they did not answer when stuck because they wanted to answer even for the view beit hashchitah is boiling—for in my humble view there is no need to say that for the view beit hashchitah is boiling there is no distinction between expelling and absorbing, only for the view of pressure there is distinction—it absorbs but does not expel; or the knife does not absorb and does not expel through pressure, only simanim are accustomed to absorb from the visible. And as Rashi wrote: for the view of pressure there is distinction—the knife is hard to absorb, but for the view beit hashchitah is boiling, the knife also absorbs—so too one can say for the Rashba's distinction: it absorbs and does not expels—meaning for the view of pressure; but for the view beit hashchitah is boiling there is no distinction. And so appears from the Rashba's language; therefore no difficulty that the reason beit hashchitah is boiling—therefore we ruled halachah in cold, meaning because simanim are busy, etc.; and automatically also with a gentile's knife halachah is like Rav Huna bar bar Chana who rinses—nevertheless we hold stringently to peel, lest like the other language of pressure—in this we can uphold halachah like Rav and distinguish knife mentioned from treifah knife because it absorbs and does not expel; if so for practical law one can say also for Tosafot that sticking helps, since it does not expel; and it is precise in this Tosafot language in what he wrote: even for the view beit hashchitah is boiling—and why did they not teach plainly for the view peel? Rather certainly as above, that for the other language of Rav's reason because of pressure, sticking also helps for Rav; rather he came to answer even for the opposing view because beit hashchitah is boiling, which expels and sticking does not help; if so, on the contrary one should be supported from Tosafot's view that by law sticking helps; and so is explained from Tosafot s.v. vehalachta, etc.—therefore he holds beit hashchitah is boiling, and nevertheless to cut cold with it sticking is not required, etc.; and whence did they learn this—that Shmuel holds beit hashchitah is boiling? Perhaps he holds absorption is because of pressure—and if so, one should ask: with absorption in boiling, sticking is required, and with absorption through pressure, sticking is not required; and if they do not want to distinguish this and hold whatever absorbs, no distinction between absorption in hot and in cold—why did they need this length? Rather he holds beit hashchitah is boiling—he should have said briefly: rather it absorbs. Rather certainly as above, he holds like Rashi: the view that says cold holds beit hashchitah is cold and the knife does not absorb; and Shmuel, who forbade cutting boiling with it, therefore holds beit hashchitah is boiling, as Rashi wrote there explicitly; if so, one can say: since because of pressure it does not absorb, likewise it does not expel; therefore they needed to say the change of building a brick in light, because they want to answer even for the view beit hashchitah is boiling—for if for the view beit hashchitah is cold, just as it does not absorb, likewise it does not expel, and sticking helps—and so as above.`,
});

patchFile('siman_010/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 10, Shach s.k. 4) <b>Because in its lifetime it stands for three things—for eating, to grow young, and for plowing,</b> end of his words. And in Kerem Shlomo he explained: for a bird, which does not have these three things—for it does not stand for labor—if so it does not spoil; see there. And it escaped me and other acharonim: that which is explicit in the Gemara Sanhedrin chapter four deaths (daf 59b), that a bird is fit for labor—namely for plowing. And it is certainly that plowing that Rashi and the Shach mention is not specifically—for in every animal it speaks, namely whose legs were cut from the knee down, that it is fit only for plowing and is kosher. And as Rashi wrote in the first chapter of Chullin (daf 7b)—see there, and think. And see in Hagahot Aharon chapter HaZahav, that a lamb is not fit for labor—and think.`,
  '2#_': `(Shach s.k. 5) <b>Sharpening helps even l'chatchila.</b> Meaning: even not in time of pressure—for in time of pressure even sticking is permitted l'chatchila, as the gloss says. But the Taz appears not to hold thus—for he wrote on what the gloss says: and in time of pressure permitted to slaughter with it in such a manner l'chatchila—explanation: if he sharpened on a whetstone or stuck in hard ground; therefore without pressure even sharpening does not help l'chatchila. And one may wonder on the Baal HaBayit Lechem Yehudah, who copied first the Shach's words and afterward the Taz's words as if in one blow—and it is not so, and requires investigation.`,
  '3#_': `(In the gloss seif 1) <b>And therefore one should peel it.</b> The reason: beit hashchitah is boiling. And furthermore, through knife pressure it absorbs—as proved explicitly in the Gemara and Tosafot and Ashrei and other poskim in the first chapter of Chullin (daf 8), that we do not say beit hashchitah is boiling and absorbs except at the end of shechitah when the animal dies.<br><b>[Said</b> the copyist Naphtali in the Gaon author's gloss: from here until the end of the matter was deleted and only these words remained: regarding a bird that they kashered in one sign, only slaughter the measure of proper shechitah. And see what he hinted at this shortly below:]`,
});

patchFile('siman_010/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `<b>Because it repairs.</b> See Ba'er Heitev. And he wrote in She'elot Ya'avetz siman 188: regarding what is written in Lechem HaPanim, that in the Temple they would hang a knife—for judgment of capital cases was done with it—and it was given to fix the shechitah knife, which becomes purified through immersion; and he wrote bitter things about avodah zarah: for what do we care about tumah and taharah, and meat that became tamei from a corpse is also permitted even for our kohanim to eat from it—only regarding the sword itself Rabbenu Tam and R' Chaim Kohen disagreed in chapter 7 of Nazir, etc. But one should be concerned: because it is prohibitions of benefit—for so the Sages taught regarding court executioners: a sword with which one was executed is buried with him; and especially if an Israelite judged with it—even though they killed not according to law, one should be concerned to judge it like an avodah zarah knife, forbidden to slaughter a dangerously ill animal with it—see there; and they already wondered at this in Beit Yehudah and Knesset HaGedolah and the Mechaber brought Ya'avetz's words and brought four (sources) from the Rambam in chapter 15 of Sanhedrin, who wrote: if they were not executed with it, only gentiles, and it does not require burial, and one may make it a knife; and it is close to say that even if an Israelite was executed with it, it is permitted—for gentiles were not commanded in this. See Yad Eliyahu siman 35 in the Rambam's language chapter 9 of Melachim regarding a gentile who relations with an animal—see there.`,
});

patchFile('siman_010/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `<b>(Siman 10 s.k. 6) And he was not precise that in siman 122, etc.</b> He intended well in this; and so I also wrote in the margin showing my place in siman 122 seif 6—not like the Derishah—see there.`,
  '2#_': `<b>(There) And in Derishah and Perishah, etc.</b> And he did not have before him, etc. And in my humble opinion the Derishah and Perishah intended well in this also according to his view—it is strained to say the Rosh speaks of a knife that is not clean, for he does not divide except whether it is ben yomo or not; it does not imply if ben yomo, even if known clean, forbidden—rather the point of sharpening and sticking is that thereby that thin peel in the knife—which sticking is everywhere in place of peeling, as Orach Chaim wrote and I brought in the Shach siman 93 s.k. 6.`,
  '3#_': `<b>(s.k. 11) He did not need to write, etc.</b> As he wrote in seif 3, etc. And to me it needs to be written—for specifically in seif 3 permitted to slaughter with it, because since simanim are busy expelling blood they do not absorb; but here one might say it absorbs—this teaches us.`,
});

patchFile('siman_010/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `<b>(a) [Seif 1] A knife of attendants of avodah zarah—new.</b> Statement of Rav Nachman and Rava, first chapter of Chullin daf 8; and he explains there: "new" means they did not use it with forbidden grease, but nevertheless they used it for avodah zarah—such as cutting wood—for if completely new, never cut with it, it is not forbidden because of avodah zarah until used for avodah zarah, as in Avodah Zarah chapter R' Yishmael (Avodah Zarah daf 52), and below siman 139. Bach. Shach s.k. 1. Peri Chadash note 1; Kereti note 1—and this is such as they cut wood with it for an avodah zarah offering. Beit Yehudah note 1; Shomer Shabbos note 2. However what he wrote there in Beit Yehudah: the same if he cut wood to make avodah zarah—Peri Chadash in Kuntres Acharon challenged him; and so Shomer Shabbos there—unless in this cutting the wood itself became avodah zarah; see there.`,
  '2#_': `<b>(b) There. Or old in which there is no concern of defilement from avodah zarah.</b> Meaning that they kashered it in a manner in which there is no concern of defilement from avodah zarah, as below siman 121. Shach s.k. 2. Peri Chadash note 2; Lechem Panim note 2; Beit Lechem Yehudah note 2; Kereti note 2.`,
  '3#_': `<b>(c) There. Permitted to slaughter with it a healthy animal, etc.</b> It implies even l'chatchila; and below siman 142 seif 2 he wrote: a knife of avodah zarah with which he slaughtered—is permitted, etc.—which implies forbidden l'chatchila when not kashered from defilement of avodah zarah; and so is explained from Hagahot HaRav there. Shach s.k. 3. Lechem Panim note 3; Zivchei Tzedek note 4. However Peri To'ar note 2 disagreed with the above Shach's words and wrote: l'chatchila forbidden as in siman 142; and what he wrote in the gloss is his own view, but according to the Shulchan Aruch forbidden l'chatchila even though kashered from defilement of avodah zarah—see there. And so Kenesset HaGedolah in Hagahat HaTur note 4.`,
});

